import pyomo.environ as pyo

DATA = {
    "n": 6,
    # "cost" maps ordered arc tuples (i -> j) to delivery cost
    "cost": {
        (1, 2): 43, (1, 3): 39, (1, 4): 97, (1, 5): 84, (1, 6): 67,
        (2, 1): 43, (2, 3): 18, (2, 4): 92, (2, 5): 27, (2, 6): 51,
        (3, 1): 39, (3, 2): 18, (3, 4): 84, (3, 5): 60, (3, 6): 15,
        (4, 1): 97, (4, 2): 92, (4, 3): 84, (4, 5): 42, (4, 6): 32,
        (5, 1): 84, (5, 2): 27, (5, 3): 60, (5, 4): 42, (5, 6): 18,
        (6, 1): 67, (6, 2): 51, (6, 3): 15, (6, 4): 32, (6, 5): 18,
    },
    "big_m": 6,
}


def build_model(data=None):
    d = data or DATA
    n = d["n"]
    costs = d["cost"]
    big_m = d["big_m"]

    model = pyo.ConcreteModel()

    # Sets
    model.cities = pyo.Set(initialize=list(range(1, n + 1)))

    # Ordered arc set (i, j) with i != j using only DATA cost keys
    def arc_init(m):
        return list(costs.keys())

    model.arcs = pyo.Set(dimen=2, initialize=arc_init)

    # Decision: arc selection variable x[i,j] on allowed arcs (no diagonal vars)
    model.subscription = pyo.Var(model.arcs, within=pyo.Binary)

    # Decision: MTZ ordering / position variable, bounded per-note
    model.order = pyo.Var(model.cities, within=pyo.Reals, bounds=(1, n))

    # Objective: minimize total route cost (linear in x)
    def obj_rule(m):
        return sum(costs[i, j] * m.subscription[i, j] for (i, j) in m.arcs)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # Constraint: exactly one incoming arc per city
    def one_in_rule(m, j):
        return sum(
            m.subscription[i, j] for (i, jj) in m.arcs if jj == j
        ) == 1

    model.one_in = pyo.Constraint(model.cities, rule=one_in_rule)

    # Constraint: exactly one outgoing arc per city
    def one_out_rule(m, i):
        return sum(
            m.subscription[i, j] for (ii, j) in m.arcs if ii == i
        ) == 1

    model.one_out = pyo.Constraint(model.cities, rule=one_out_rule)

    # Constraint: MTZ subtour elimination (for i != j, (i,j) in arcs)
    def mtz_rule(m, i, j):
        return (
            m.order[j]
            >= m.order[i] + 1 - big_m * (1 - m.subscription[i, j])
        )

    model.mtz = pyo.Constraint(model.arcs, rule=mtz_rule)

    return model


